//! Independent held hammer conversion through registered typed World actions.
use gielinor_world::{held_item_conversion::Rule,inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,hits::{Hit,Target,Style},CoordGrid};
fn fixture(reverse:bool,member:bool,selected:usize,sparse:bool)->(World,ActorId,i32,i32){let(input,output)=if reverse{(29775,25644)}else{(25644,29775)};let mut w=World::default();w.collision.allocate(3200,3200,0);for(a,b)in[(25644,29775),(29775,25644)]{w.empty_containers.insert(a,Rule{output:b,members:false,button_operation:4,message:None});}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_current(12,0);let mut d=PlayerData::new(1,"Independent held hammer".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}let duplicate=(selected+1)%28;for s in[selected,duplicate]{d.inventory.restore_slot(s,Some(Item{id:input,count:1,vars:0})).unwrap();}if sparse{for s in(0..28).filter(|s|*s!=selected && *s!=duplicate).take(3){d.inventory.restore_slot(s,None).unwrap();}}d.equipment.restore_slot(0,Some(Item{id:1129,count:1,vars:7})).unwrap();w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.tick().unwrap();w.drain_events();w.data_mut(a).unwrap().inventory.clear_modified();(w,a,input,output)}
#[test]fn fifty_three_remaining_life_metadata_context_refusals(){let mut n=0;for reverse in[false,true]{for member in[false,true]{for case in 0..16{if !reverse && !member && case<11{continue;}let(mut w,a,input,output)=fixture(reverse,member,17,false);let mut claim=input;match case{
0=>claim=output,
1=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:input,count:1,vars:1})).unwrap();},
2=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:input,count:2,vars:0})).unwrap();},
3=>{w.data_mut(a).unwrap().inventory.restore_slot(17,None).unwrap();},
4=>{w.object_types.dummy.insert(input);},5=>{w.object_types.dummy.insert(output);},6=>{w.object_types.stackable.insert(input);},7=>{w.object_types.stackable.insert(output);},
8=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:1931,count:1,vars:0})).unwrap();},
9=>w.set_modal_open(a,true).unwrap(),10=>w.delay_player(a,4).unwrap(),11=>w.request_logout(a).unwrap(),12=>{w.data_mut(a).unwrap().stats.set_current(3,0);},
13=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick().unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);},
14=>w.data_mut(a).unwrap().inventory.placeholders=true,_=>{w.empty_containers.remove(&input);}}
if case!=11{w.data_mut(a).unwrap().inventory.clear_modified();}let before=w.data(a).unwrap().clone();w.drain_events();let _=w.submit(a,Action::ConvertHeldItem{slot:17,item:claim});for _ in 0..4{w.tick().unwrap();}let d=w.data(a).unwrap();assert_eq!(d.inventory,before.inventory,"reverse{reverse} member{member} case{case}");assert_eq!(d.equipment,before.equipment);assert_eq!(d.stats,before.stats);assert!(d.inventory.modified().is_empty());assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..}|WorldEvent::EquipmentResult{..}|WorldEvent::PlayerCombatAnimation{..})));n+=1;}}}assert_eq!(n,53);println!("PG_IMCANDO_HELD atomic_refusals={n}");}
